import React, { Component } from "react";
import pagesJson from "./pages";

export default class Aboutus extends Component {
    render() {
        // נמצא את העמוד "AboutUs" במערך
        const aboutUsPage = pagesJson.find((page) => page.PageName === "AboutUs");

        // אם לא נמצא העמוד, נחזיר null
        if (!aboutUsPage) {
            return null;
        }

        // אם נמצא העמוד, נחזיר את רקע התוכן שלו
        const { content } = aboutUsPage;

        return (
            <div className="desc">
                <ul>
                    {content.map((item, index) => (
                        <li key={index}>{item}</li>
                    ))}
                </ul>
            </div>
        );
    }
}
